-- Allow explicit delivery-date corrections while retaining idempotent stock allocations.
create or replace function private.save_order(target_workspace uuid,order_id uuid,order_data jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare previous public.orders;n public.orders;p public.inventory;m public.team_members;is_update boolean;terms_changed boolean;eligible boolean;cost numeric;begin
 perform private.require_role(target_workspace,array['admin','manager','staff']);
 select * into previous from public.orders where id=order_id for update;is_update:=found;if is_update and previous.workspace_id<>target_workspace then raise exception 'Order not found';end if;
 n:=jsonb_populate_record(null::public.orders,order_data);n.id:=order_id;n.workspace_id:=target_workspace;n.created_at:=case when is_update then previous.created_at else now() end;n.created_by:=case when is_update then previous.created_by else auth.uid() end;
 n.date:=coalesce(case when is_update then previous.date else n.date end,(now() at time zone 'Africa/Casablanca')::date);n.status:=coalesce(n.status,'new');n.quantity:=coalesce(n.quantity,1);n.unit_cost:=coalesce(n.unit_cost,0);n.shipping_charged:=coalesce(n.shipping_charged,0);n.shipping_cost:=coalesce(n.shipping_cost,0);n.platform_fee:=coalesce(n.platform_fee,0);n.buyer_name:=coalesce(n.buyer_name,'');n.payment_method:=coalesce(n.payment_method,'cash');n.fulfillment_type:=coalesce(n.fulfillment_type,'local_pickup');n.stock_allocations:='[]';
 if n.quantity<=0 or n.sale_price is null or n.sale_price<0 then raise exception 'Invalid quantity or price';end if;
 terms_changed:=not is_update or n.item_id is distinct from previous.item_id or n.quantity<>previous.quantity or (n.status in ('delivered','completed')) is distinct from (previous.status in ('delivered','completed'));
 if is_update and terms_changed and previous.status in ('delivered','completed') then perform private.restore(target_workspace,previous.stock_allocations);end if;
 if n.item_id is not null then select * into strict p from public.inventory where workspace_id=target_workspace and id=n.item_id; if p.status='archived' and (not is_update or n.item_id is distinct from previous.item_id) then raise exception 'Product is archived';end if;n.item_title:=p.title;n.base_price:=p.selling_price;n.unit_cost:=p.cost_price;else n.base_price:=coalesce(n.sale_price,0);end if;
 if n.status in ('delivered','completed') then
 if not terms_changed then n.stock_allocations:=previous.stock_allocations;n.unit_cost:=previous.unit_cost;elsif n.item_id is not null then n.stock_allocations:=private.consume(target_workspace,n.item_id,n.quantity,'delivery',order_id);select sum((a->>'quantity')::numeric*(a->>'costPrice')::numeric)/n.quantity into cost from jsonb_array_elements(n.stock_allocations) a;n.unit_cost:=cost;end if;
 n.delivered_date:=coalesce(n.delivered_date,case when is_update and previous.status in ('delivered','completed') then previous.delivered_date end,(now() at time zone 'Africa/Casablanca')::date);
 else n.delivered_date:=null;end if;
 n.member_reward:=0;n.reward_status:=case when n.status='cancelled' then 'cancelled' else 'pending' end;
 if n.confirmation_member_id is not null then
 select * into strict m from public.team_members where workspace_id=target_workspace and id=n.confirmation_member_id;n.confirmation_member_name:=m.name;n.reward_trigger:=m.reward_trigger;n.reward_calculation_mode:=m.reward_calculation_mode;
 eligible:=n.status in ('delivered','completed') or (m.reward_trigger='confirmed' and n.status in ('confirmed','pending_pickup','shipped'));
 if eligible then n.reward_status:='granted';
 if is_update and previous.reward_status='granted' and previous.confirmation_member_id=n.confirmation_member_id and previous.quantity=n.quantity and previous.sale_price=n.sale_price and previous.item_id is not distinct from n.item_id then n.member_reward:=previous.member_reward;n.base_price:=previous.base_price;
 else n.member_reward:=round(m.base_reward*case when m.reward_calculation_mode='per_item' then n.quantity else 1 end+greatest(n.sale_price-n.base_price,0)*n.quantity,2);end if;end if;
 end if;
 n.total_revenue:=round(n.sale_price*n.quantity+n.shipping_charged,2);n.total_cost:=round(n.unit_cost*n.quantity+n.shipping_cost+n.platform_fee,2);n.net_profit:=case when n.status='cancelled' then 0 else n.total_revenue-n.total_cost-n.member_reward end;n.profit_margin:=case when n.total_revenue>0 then round(n.net_profit*100/n.total_revenue,2) else 0 end;
 insert into public.orders select n.* on conflict(id) do update set workspace_id=excluded.workspace_id,item_id=excluded.item_id,item_title=excluded.item_title,quantity=excluded.quantity,unit_cost=excluded.unit_cost,sale_price=excluded.sale_price,shipping_charged=excluded.shipping_charged,shipping_cost=excluded.shipping_cost,platform_fee=excluded.platform_fee,total_revenue=excluded.total_revenue,total_cost=excluded.total_cost,net_profit=excluded.net_profit,profit_margin=excluded.profit_margin,buyer_name=excluded.buyer_name,customer_phone=excluded.customer_phone,customer_address=excluded.customer_address,google_maps_url=excluded.google_maps_url,payment_method=excluded.payment_method,fulfillment_type=excluded.fulfillment_type,carrier=excluded.carrier,tracking_number=excluded.tracking_number,status=excluded.status,date=excluded.date,delivered_date=excluded.delivered_date,notes=excluded.notes,created_at=excluded.created_at,created_by=excluded.created_by,confirmation_member_id=excluded.confirmation_member_id,confirmation_member_name=excluded.confirmation_member_name,base_price=excluded.base_price,member_reward=excluded.member_reward,reward_trigger=excluded.reward_trigger,reward_status=excluded.reward_status,reward_calculation_mode=excluded.reward_calculation_mode,stock_allocations=excluded.stock_allocations;
 perform private.refresh_bundles(target_workspace);return order_id;
end $$;
